import AppKit

// A stand-in for EditorViewController's upperSplit: the same delegate answers,
// the same holding priorities, the same minimums. Posts a divider drag.
final class PaneSplit: NSSplitView {}

final class Del: NSObject, NSSplitViewDelegate {
    let inspector: NSView
    init(_ inspector: NSView) { self.inspector = inspector }
    func splitView(_ s: NSSplitView, constrainMinCoordinate p: CGFloat, ofSubviewAt i: Int) -> CGFloat {
        max(380, s.bounds.width - 440)
    }
    func splitView(_ s: NSSplitView, constrainMaxCoordinate p: CGFloat, ofSubviewAt i: Int) -> CGFloat {
        max(380, s.bounds.width - 280)
    }
    func splitView(_ s: NSSplitView, canCollapseSubview v: NSView) -> Bool { v === inspector }
    func splitView(_ s: NSSplitView, shouldHideDividerAt i: Int) -> Bool { false }
}

let app = NSApplication.shared
app.setActivationPolicy(.accessory)
let window = NSWindow(
    contentRect: NSRect(x: 100, y: 100, width: 1200, height: 500),
    styleMask: [.titled, .resizable], backing: .buffered, defer: false)
let split = PaneSplit(frame: NSRect(x: 0, y: 0, width: 1200, height: 500))
split.isVertical = true
split.dividerStyle = .thin
let canvas = NSView()
let inspector = NSView()
let del = Del(inspector)
split.delegate = del
split.addArrangedSubview(canvas)
split.addArrangedSubview(inspector)
split.setHoldingPriority(NSLayoutConstraint.Priority(249), forSubviewAt: 0)
split.setHoldingPriority(NSLayoutConstraint.Priority(251), forSubviewAt: 1)
window.contentView = split
window.orderFront(nil)
split.layoutSubtreeIfNeeded()

func event(_ type: NSEvent.EventType, _ x: CGFloat) -> NSEvent {
    NSEvent.mouseEvent(
        with: type, location: NSPoint(x: x, y: 250), modifierFlags: [], timestamp: 0,
        windowNumber: window.windowNumber, context: nil, eventNumber: 0, clickCount: 1,
        pressure: 1)!
}

func report(_ label: String) {
    print(label, "inspector width", inspector.frame.width, "hidden", inspector.isHidden,
        "collapsed", split.isSubviewCollapsed(inspector))
}

func drag(to x: CGFloat) {
    let start = canvas.frame.maxX + 0.5
    app.postEvent(event(.leftMouseDragged, x), atStart: false)
    app.postEvent(event(.leftMouseUp, x), atStart: false)
    split.mouseDown(with: event(.leftMouseDown, start))
    split.layoutSubtreeIfNeeded()
}

split.setPosition(1200 - 304 - split.dividerThickness, ofDividerAt: 0)
split.layoutSubtreeIfNeeded()
report("start")
for x: CGFloat in [950, 1000, 1050, 1059, 1061, 1100, 1190] {
    split.setPosition(1200 - 304 - split.dividerThickness, ofDividerAt: 0)
    inspector.isHidden = false
    split.adjustSubviews()
    split.layoutSubtreeIfNeeded()
    drag(to: x)
    report("drag to \(x):")
}
// Drag back out from collapsed.
drag(to: 800)
report("drag back to 800:")
exit(0)

