import AVFoundation
import Foundation

// Playback.swift's loop logic on a real AVPlayer over a composition: a 1/60 s
// periodic observer, actionAtItemEnd = .pause, a seek to the loop's start when
// a tick with rate != 0 is at or past the loop's end.
let path = CommandLine.arguments[1]
let loopEndFraction = Double(CommandLine.arguments[2]) ?? 1
let asset = AVURLAsset(url: URL(fileURLWithPath: path))
let composition = AVMutableComposition()
let full = CMTimeRange(start: .zero, duration: asset.duration)
try composition.insertTimeRange(full, of: asset, at: .zero)
let duration = composition.duration.seconds
let loopEnd = duration * loopEndFraction
print("duration", duration, "loop end", loopEnd)

let item = AVPlayerItem(asset: composition)
let player = AVPlayer(playerItem: item)
player.isMuted = true
player.actionAtItemEnd = .pause
player.automaticallyWaitsToMinimizeStalling = false

var seeks = 0
var isSeeking = false
var lastTicks: [(Double, Float)] = []
let observer = player.addPeriodicTimeObserver(
    forInterval: CMTime(value: 1, timescale: 60), queue: .main
) { time in
    lastTicks.append((time.seconds, player.rate))
    if lastTicks.count > 6 { lastTicks.removeFirst() }
    guard player.rate != 0, time.seconds >= loopEnd, !isSeeking else { return }
    seeks += 1
    isSeeking = true
    print("loop seek at", time.seconds, "rate", player.rate)
    player.seek(to: .zero, toleranceBefore: .zero, toleranceAfter: .zero) { _ in
        isSeeking = false
        print("  seek done, rate", player.rate)
    }
}
let rateWatch = player.observe(\.rate, options: [.new]) { p, _ in
    print("rate ->", p.rate, "at", p.currentTime().seconds)
}

player.play()
let started = Date()
RunLoop.main.run(until: started.addingTimeInterval(9))
print("after 9 s: time", player.currentTime().seconds, "rate", player.rate, "seeks", seeks)
print("last ticks", lastTicks)
_ = observer
_ = rateWatch
exit(0)

